INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('1', '1', '0', 'Preparing The Batter', 'Sift flour and salt into a bowl. Create a well in the centre and drop in the egg.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('2', '1', '1', '', 'Add half the liquids (includes butter) in small increments at a time and mix until smooth.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('3', '1', '2', '', 'Beat in the remaining liquid and stir until it has the consistency of thin cream.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('4', '1', '3', 'Cooking', 'Pour a small amount (only enough to coat the bottom of the pan) into a frypan over medium heat.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('5', '1', '4', '', 'Flip the pancake over once the underside is mostly cooked.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('6', '1', '5', '', 'Once the pancake is cooked, serve it with your choice of toppings.', 'data:image/webp;base64,');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('7', '2', '0', '', 'Combine Drained and flaked tuna, onion flakes, lemon juice, parsley and garlic salt. ', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('8', '2', '1', 'White Sauce', 'In a pot over the stove, melt the marg and blend in flour and seasonings. Add the milk very gradually and cook until it is thick and smooth, stirring constantly.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('9', '2', '2', '', 'Fold in the tuna mixture and breadcrumbs and place the mixture in a casserole dish.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('10', '2', '3', '', 'Cover with potato crisps.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('11', '2', '4', 'Cooking It', 'Cook at 400 degrees F for 20 mins.', 'data:image/webp;base64,');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('12', '3', '0', '1', 'Place eggs in a saucepan and cover with water. Bring to the boil then cook for 10 minutes. Drain and cover with cold water. After 2 minutes, drain again and cover with cold water again. Remove 1 egg at a time and peel then slice.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('13', '3', '1', '2', 'Lay out 4 plates and place a layer of egg slices on each plate, topped with flaked tuna, then cucumber, then tomato.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('14', '3', '2', '3', 'Mix remaining ingredients to create a sauce and drizzle over.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('15', '4', '0', '1', 'Peel and mash banana. Place all ingredients in blender or milkshake maker and mix for 1 minute.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('16', '5', '0', '1', 'Sift flour and pepper.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('17', '5', '1', '2', 'Rub in margarine.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('18', '5', '2', '3', 'Add cheese and milk and mix to a soft dough.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('19', '5', '3', '4', 'Place 8 spoonsful on a paper-lined baking tray and shape into rounds.', '');
INSERT INTO "step" ("id", "recipe_id", "step_number", "name", "desc", "photo") VALUES ('20', '6', '0', '', 'Combine all ingredients.', '');
